-- Puente para el backend JSONB actual; NO migra el modelo relacional.
-- No modifica users, sessions, tours, reservations ni otras tablas existentes.
-- Usuarios/catalogo/reservas del modelo relacional NO seran visibles en este store.
-- Administrador deshabilitado (password null), sin credenciales predeterminadas.
-- Rotacion explicita posterior: scripts/rotate-admin.mjs --rotate-admin.
-- No habilita pagos reales. Revisar datos comerciales antes de operar.
BEGIN;
CREATE SCHEMA IF NOT EXISTS kanba_rel;

CREATE TABLE IF NOT EXISTS kanba_rel.kanba_store (
  id smallint PRIMARY KEY CHECK (id = 1),
  doc jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS kanba_rel.kanba_rate_limits (
  key text PRIMARY KEY,
  window_start timestamptz NOT NULL,
  count integer NOT NULL
);
CREATE TABLE IF NOT EXISTS kanba_rel.kanba_oauth_states (
  state text PRIMARY KEY,
  next text NOT NULL,
  expires_at timestamptz NOT NULL,
  browser_hash text NOT NULL
);
-- Tambien requerida por server/db.js para archivos subidos.
CREATE TABLE IF NOT EXISTS kanba_rel.kanba_media (
  name text PRIMARY KEY,
  mime text NOT NULL,
  size integer NOT NULL,
  data bytea NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO kanba_rel.kanba_store (id, doc)
VALUES (1, jsonb_build_object(
  'meta', jsonb_build_object('version', 1, 'createdAt', now(), 'updatedAt', now()),
  'admin', jsonb_build_object('password', NULL, 'passwordPolicyVersion', 2, 'updatedAt', now()),
  'users', '[]'::jsonb,
  'sessions', '{}'::jsonb,
  'userSessions', '{}'::jsonb,
  'counters', '{"reservation":0,"receipt":0}'::jsonb,
  'content', '{"brand":{"name":"K’anba","sub":"Cuevas Vivas","tagline":"Donde el río se esconde","claim":"Una aventura de agua, piedra y el río en el corazón de Alta Verapaz."},"hero":{"kicker":"Lanquín · Alta Verapaz · Guatemala","title":"K’anba","subtitle":"Donde el río se esconde.","text":"Entra a una cueva viva de río subterráneo. Con una vela en la mano, el sonido del agua y un guía q’eqchi’, cruzarás pasadizos, cascadas y pozas de luz imposible. A minutos de Semuc Champey.","image":"/assets/img/kanba-cave-02.jpg","imageAlt":"Interior de una cueva de Lanquín iluminada con luz frontal","badge":"Cupos limitados · 12 personas por grupo","openText":"Abierto todos los días · 08:00 a 17:00","rating":"4.9","reviews":"312"},"intro":{"kicker":"La cueva","title":"Un río que corre bajo la montaña","lead":"K’anba es una cueva de río, no un salón iluminado. Aquí el agua marca el camino: a veces a los tobillos, a veces al pecho. La piedra caliza se abre en galerías de cinco a diez metros de ancho y el Cahabón sigue su viaje secreto bajo la selva.","paragraphs":["El sistema explorado supera los 3.3 kilómetros, aunque la visita guiada recorre los primeros 400 metros: un tramo seguro, profundo y lleno de formas que la luz frontal convierte en otra cosa. Al salir, el río te devuelve a la superficie y puedes flotar en cámara lenta por el Cahabón.","Para el pueblo q’eqchi’, la cueva no es solo un atractivo: es un umbral. El agua, la oscuridad y las formaciones de piedra han sido parte de su cosmovisión durante generaciones. Nuestros guías son locales y comparten esa lectura del territorio en cada grupo.","En 2004, espeleólogos guatemaltecos con apoyo de colegas estadounidenses exploraron y levantaron el sistema; el trabajo de topografía concluyó en marzo de 2005. Hoy la visita se hace en grupos pequeños, con equipo de seguridad y reglas claras para proteger el ecosistema."],"stats":[{"value":"3.3","suffix":" km","label":"de galerías exploradas"},{"value":"400","suffix":" m","label":"de recorrido guiado"},{"value":"90","suffix":"%","label":"del trayecto es agua"},{"value":"12","suffix":"","label":"personas máximo por grupo"}],"image":"/assets/img/kanba-cave-04.jpg","image2":"/assets/img/kanba-river-01.jpg"},"values":[{"icon":"flame","title":"El silencio es el sendero","text":"Sin luz eléctrica dentro de la cueva. Una linterna frontal por persona, un guía al frente y una cuerda que une al grupo. La oscuridad no se atraviesa: se escucha."},{"icon":"water","title":"El río dicta el paso","text":"Caminas, te sostienes de la roca y nadas tramos cortos. Hay una cascada que se sube con cuerda y saltos opcionales a pozas profundas. Se siente más de lo que se ve."},{"icon":"leaf","title":"Custodia q’eqchi’","text":"Guías de comunidades de Lanquín lideran cada expedición. Parte del ingreso se destina a conservación, mantenimiento de senderos y educación ambiental local."}],"timeline":[{"year":"2004","title":"Primera gran exploración","text":"Espeleólogos guatemaltecos, con apoyo internacional, documentan las galerías y el río interior."},{"year":"2005","title":"Levantamiento topográfico","text":"En marzo concluye la topografía del sistema, que supera los 3.3 km de desarrollo conocido."},{"year":"2010","title":"Turismo de aventura","text":"La cueva se integra a las rutas de Semuc Champey. Nacen los recorridos de aventura y el tubing."},{"year":"Hoy","title":"Turismo comunitario","text":"Grupos pequeños, guías locales y reglas de conservación para que la cueva siga viva."}],"toursIntro":{"kicker":"Experiencias","title":"Elige cómo entrar a la cueva","text":"Cinco formas de vivir K’anba. Todas incluyen guía local certificado, casco, chaleco salvavidas y entrada. Los cupos se confirman al pagar."},"bookingIntro":{"kicker":"Reserva en línea","title":"Tu lugar bajo tierra","text":"Selecciona experiencia, fecha, horario y participantes. Bloqueamos tus cupos por 20 minutos mientras completas el pago."},"galleryIntro":{"kicker":"Archivo visual","title":"La cueva, el río y la selva","text":"Una colección de imágenes del karst de Lanquín, el Cahabón y Semuc Champey. Fotografías de referencia del entorno y del sistema subterráneo."},"videosIntro":{"kicker":"En movimiento","title":"Antes de entrar, mírala","text":"Seis ventanas a la experiencia: el río, la selva y la cascada y el paisaje que rodea la cueva."},"mapIntro":{"kicker":"Cómo llegar","title":"Un desvío antes del puente","text":"K’anba está sobre la ruta a Semuc Champey, en Lanquín. Si vienes desde Cobán, el último tramo es de terracería: recomendamos doble tracción o transporte local.","address":"Cuevas de K’anba, Lanquín, Alta Verapaz, Guatemala","lat":15.537628,"lng":-89.955361,"plusCode":"G2QV+3V2 Chicanutz, Guatemala","directions":[{"label":"Desde Lanquín","value":"11 km · 25–35 min en pickup o 4x4"},{"label":"Desde Semuc Champey","value":"10 min caminando · 400 m antes del puente"},{"label":"Desde Cobán","value":"80 km · 2 h aprox. (último tramo de terracería)"},{"label":"Desde Ciudad de Guatemala","value":"294 km · 5–6 h por CA-14"}],"note":"No cruces el puente principal hacia Semuc Champey: el acceso a K’anba está antes, a la derecha. Hay parqueo comunitario y recepción."},"infoIntro":{"kicker":"Antes de bajar","title":"Prepárate bien. La cueva no perdona la prisa.","text":"K’anba es una aventura acuática real. Lee los requisitos, las recomendaciones y las restricciones antes de reservar. Si tienes dudas de salud, consulta a tu médico."},"requirements":["Edad mínima: 8 años acompañados por un adulto; 12 años para el recorrido completo sin acompañamiento permanente.","Saber nadar o usar chaleco salvavidas (obligatorio en todos los tramos profundos).","Condición física moderada: caminar sobre roca húmeda, agacharse, trepar y nadar distancias cortas.","Firmar la carta de responsabilidad y aceptar las instrucciones del guía antes de entrar.","Presentar documento de identidad o pasaporte en recepción (puede ser digital).","Llegar 20 minutos antes del horario reservado para equipo y briefing.","Calzado cerrado con agarre que se pueda mojar. No se permite entrar descalzo ni con chanclas sueltas.","Para menores de edad: autorización firmada por madre, padre o tutor legal."],"recommendations":["Viaja en temporada seca (noviembre a abril) para agua más clara y senderos más firmes.","Elige el primer horario del día: menos calor, menos gente y mejor luz para fotos al salir.","Lleva ropa de cambio completa, toalla y una bolsa impermeable para el teléfono.","Usa protector solar y repelente biodegradables; se aplican antes de entrar, no dentro de la cueva.","Lleva efectivo en billetes pequeños para transporte, propinas y compras locales. No hay cajero en el parque.","Come algo ligero antes del tour. Evita comidas pesadas y alcohol.","Si usas lentes de contacto, considera gafas de agua o una correa de sujeción.","Respeta los lugares sagrados q’eqchi’ y pide permiso antes de fotografiar a personas de la comunidad."],"restrictions":["No se permite el ingreso a personas embarazadas, con problemas cardíacos, epilepsia no controlada, claustrofobia severa o lesiones recientes.","Prohibido el alcohol y las drogas antes o durante la actividad. El guía puede negar el ingreso sin reembolso.","No se permite fumar, encender fuego ni usar velas fuera de los soportes entregados.","No se permite tocar, romper ni llevarse estalactitas, estalagmitas, rocas o material biológico.","No se permite alimentar animales, molestar murciélagos ni usar flash directo sobre las colonias.","No se permite el ingreso con mascotas, vidrio, alimentos, bocinas o drones sin permiso.","No se permite la desnudez, los gritos, empujar o separarse del grupo dentro de la cueva.","El uso de casco y chaleco salvavidas es obligatorio y no es negociable. Menores siempre de la mano de un adulto.","La cueva puede cerrarse por lluvia fuerte, crecida del río o mantenimiento. En ese caso se reprograma o reembolsa."],"policiesIntro":{"kicker":"Transparencia","title":"Políticas de reserva, cancelación y reembolso","text":"Reservar en línea implica aceptar estas condiciones. Están diseñadas para proteger al visitante, al equipo local y al ecosistema. Última actualización: enero de 2026."},"policies":[{"id":"reserva","title":"Reservas y bloqueo de cupos","summary":"Los cupos se separan durante 20 minutos mientras completas el pago.","items":["Toda reserva se crea con un número único (formato KAN-AAAA-#####) y un enlace privado de pago.","Al iniciar el proceso, los cupos quedan bloqueados temporalmente por 20 minutos.","Si el pago no se completa en ese plazo, la reserva expira automáticamente y los cupos vuelven a estar disponibles.","La reserva queda confirmada únicamente cuando la pasarela de pago aprueba el importe total.","Recibirás un correo de confirmación y un comprobante digital inmediatamente después del pago aprobado."]},{"id":"pago","title":"Pagos y comprobantes","summary":"Pago en línea con tarjeta a través de pasarela segura; el cargo se procesa en quetzales.","items":["Los precios se publican en quetzales guatemaltecos (GTQ) e incluyen impuestos aplicables.","El cargo se realiza en el momento de la compra mediante la pasarela de pagos habilitada.","No almacenamos números completos de tarjeta ni códigos CVV. Solo conservamos los últimos cuatro dígitos y la marca.","El comprobante digital se envía al correo registrado y puede imprimirse o guardarse como PDF.","Si el pago es rechazado, los cupos se mantienen bloqueados hasta que venza el plazo o completes otro intento."]},{"id":"cancelacion","title":"Cancelación por el visitante","summary":"Reembolso del 100% hasta 72 h antes; 50% entre 72 y 24 h; sin reembolso con menos de 24 h.","items":["Con 72 horas o más de anticipación: reembolso del 100% del importe pagado.","Entre 72 y 24 horas antes: reembolso del 50%.","Con menos de 24 horas o no presentación (no-show): no aplica reembolso.","Las solicitudes se registran desde “Mi reserva” o escribiendo a reservas@kanba.gt con el número de reserva.","Los reembolsos se procesan al medio de pago original y pueden tardar de 5 a 10 días hábiles en reflejarse.","Se permite un cambio de fecha sin cargo hasta 48 horas antes, sujeto a disponibilidad y una sola vez por reserva."]},{"id":"clima","title":"Clima, seguridad y cierres","summary":"La cueva es un entorno natural: si no es seguro entrar, se reprograma o se reembolsa.","items":["La operación puede suspenderse por lluvia intensa, crecida del río, rayos o mantenimiento.","Si la empresa cancela la actividad, el visitante elige reprogramación sin costo o reembolso del 100%.","Si el visitante decide no continuar por miedo, fatiga o condiciones personales, no aplica reembolso una vez iniciado el briefing.","El guía tiene la última palabra sobre la seguridad del grupo y puede excluir a una persona del recorrido.","Los itinerarios pueden ajustarse por condiciones del camino, tráfico o causas de fuerza mayor."]},{"id":"reembolsos","title":"Reembolsos y registro","summary":"Cada cancelación y reembolso queda registrado con folio, importe, método y fecha.","items":["Toda cancelación genera un registro interno con folio, fecha, motivo e importe calculado.","Los reembolsos aprobados se registran en el libro de reembolsos con estado “pendiente” o “procesado”.","El reembolso se emite al medio de pago original cuando la pasarela lo permite.","Si la pasarela no permite reversa automática, se coordina transferencia bancaria con el titular.","Recibirás un correo cuando el reembolso sea procesado, con el número de referencia.","Los cargos por conversión de moneda o comisiones bancarias del emisor no son reembolsables por K’anba."]},{"id":"privacidad","title":"Datos personales y privacidad","summary":"Usamos tus datos solo para operar la reserva y cumplir obligaciones legales.","items":["Recopilamos nombre, correo, teléfono, país y documento de identidad cuando se solicita.","Los datos se usan para confirmar la reserva, emitir comprobantes, gestionar cancelaciones y seguridad del grupo.","No vendemos ni compartimos datos con terceros ajenos a la operación del tour o la pasarela de pago.","Puedes solicitar acceso, corrección o eliminación escribiendo a reservas@kanba.gt.","Las tarjetas se procesan en la pasarela; K’anba no recibe ni almacena el número completo.","Los correos transaccionales son necesarios para la reserva y no requieren consentimiento publicitario."]}],"faq":[{"q":"¿Necesito saber nadar para entrar a K’anba?","a":"No es indispensable si usas chaleco salvavidas, que es obligatorio. Aun así, debes sentirte cómodo con agua al pecho y con la oscuridad. Si no sabes nadar y sientes ansiedad, elige el tour “K’anba Suave” por senderos y pozas."},{"q":"¿Qué tan oscura y estrecha es la cueva?","a":"La ruta es oscura y húmeda, con pasadizos de 5 a 10 metros de ancho y algunos tramos bajos. No es una cueva de gatear durante horas, pero sí exige confianza. Personas con claustrofobia severa no deberían entrar."},{"q":"¿Puedo llevar mi teléfono o cámara?","a":"Sí, con funda impermeable y correa. La condensación y los salpicones son constantes. No se permite flash sobre los murciélagos ni drones. El guía puede pedirte guardar el equipo en tramos de nado."},{"q":"¿Cómo llego sin auto?","a":"Desde Lanquín salen pickups y tuk-tuks hacia Semuc Champey; pide bajarte en el desvío de K’anba, antes del puente. También ofrecemos transporte de ida y vuelta en el tour K’anba + Semuc Champey."},{"q":"¿Qué pasa si llueve?","a":"La cueva puede cerrarse por seguridad si el río crece. Te avisaremos por correo o teléfono. Puedes reprogramar sin costo o solicitar reembolso del 100% si la cancelación es nuestra."},{"q":"¿Hay estacionamiento y vestidores?","a":"Sí: parqueo comunitario, recepción, baños y un área rústica para cambiarte. No hay casilleros de alta seguridad; viaja con lo indispensable y deja objetos de valor en tu hospedaje."},{"q":"¿Es accesible para silla de ruedas?","a":"La cueva no es accesible. El sendero de K’anba Suave tiene tramos irregulares y escaleras; podemos adaptar el ritmo, pero no garantizamos acceso universal. Escríbenos para evaluar tu caso."},{"q":"¿Los guías hablan inglés?","a":"Sí, todos los tours regulares tienen guía bilingüe español/inglés. Otros idiomas se coordinan con anticipación según disponibilidad."}],"contact":{"phone":"+502 4000 2026","whatsapp":"+50240002026","email":"reservas@kanba.gt","address":"Cuevas de K’anba, Lanquín, Alta Verapaz, Guatemala","hours":"Todos los días · 08:00 a 17:00","instagram":"@kanba.cuevas","facebook":"K’anba Cuevas Vivas","emergency":"+502 4000 2027"},"footerNote":"Sitio demostrativo creado con fines educativos. No es el sitio oficial de las Cuevas de K’anba. Las fotografías del entorno provienen de Wikimedia Commons y se usan con sus licencias Creative Commons.","gallery":[{"id":"img_01","src":"/assets/img/kanba-cave-01.jpg","caption":"Luz frontal sobre la roca caliza","category":"cueva","credit":"Wikimedia Commons · CC BY-SA 3.0"},{"id":"img_02","src":"/assets/img/kanba-cave-02.jpg","caption":"Galería húmeda del karst de Lanquín","category":"cueva","credit":"Wikimedia Commons · CC BY 2.0"},{"id":"img_03","src":"/assets/img/kanba-cave-03.jpg","caption":"Formaciones y sombras del río subterráneo","category":"cueva","credit":"Wikimedia Commons · CC BY 2.0"},{"id":"img_04","src":"/assets/img/kanba-cave-04.jpg","caption":"El techo de piedra y sus pliegues","category":"cueva","credit":"Wikimedia Commons · CC BY-SA 4.0"},{"id":"img_05","src":"/assets/img/kanba-cave-05.jpg","caption":"La boca de la cueva, umbral entre dos mundos","category":"cueva","credit":"Wikimedia Commons · CC BY-SA 4.0"},{"id":"img_06","src":"/assets/img/kanba-cave-06.jpg","caption":"El Cahabón reaparece entre las rocas","category":"cueva","credit":"Wikimedia Commons · CC BY 2.0"},{"id":"img_07","src":"/assets/img/kanba-river-01.jpg","caption":"Aguas turquesa del Cahabón","category":"rio","credit":"Wikimedia Commons · CC BY-SA 3.0"},{"id":"img_08","src":"/assets/img/kanba-river-02.jpg","caption":"El río Cahabón a su paso por Semuc Champey","category":"rio","credit":"Wikimedia Commons · CC BY 3.0"},{"id":"img_09","src":"/assets/img/kanba-jungle-01.jpg","caption":"Selva húmeda de Alta Verapaz","category":"selva","credit":"Wikimedia Commons · CC BY 2.0"},{"id":"img_10","src":"/assets/img/kanba-jungle-02.jpg","caption":"El verde profundo de la montaña","category":"selva","credit":"Wikimedia Commons · CC BY 2.0"},{"id":"img_11","src":"/assets/img/kanba-jungle-03.jpg","caption":"Sendero entre helechos y roca","category":"selva","credit":"Wikimedia Commons · CC BY 2.0"},{"id":"img_12","src":"/assets/img/kanba-jungle-04.jpg","caption":"El bosque que guarda el río","category":"selva","credit":"Wikimedia Commons · CC BY 2.0"},{"id":"img_13","src":"/assets/img/kanba-pools-01.jpg","caption":"Pozas escalonadas de Semuc Champey","category":"semuc","credit":"Wikimedia Commons · CC BY-SA 4.0"},{"id":"img_14","src":"/assets/img/kanba-pools-02.jpg","caption":"El puente natural de piedra caliza","category":"semuc","credit":"Wikimedia Commons · CC BY-SA 4.0"},{"id":"img_15","src":"/assets/img/kanba-pools-03.jpg","caption":"Agua clara sobre el puente de roca","category":"semuc","credit":"Wikimedia Commons · CC BY-SA 4.0"},{"id":"img_16","src":"/assets/img/kanba-pools-04.jpg","caption":"Piscinas naturales en la selva","category":"semuc","credit":"Wikimedia Commons · CC BY-SA 4.0"},{"id":"img_17","src":"/assets/img/kanba-pools-05.jpg","caption":"El mirador sobre las pozas","category":"semuc","credit":"Wikimedia Commons · CC BY-SA 4.0"},{"id":"img_18","src":"/assets/img/kanba-pools-06.jpg","caption":"Un santuario de agua turquesa","category":"semuc","credit":"Wikimedia Commons · CC BY-SA 3.0"}],"videos":[{"id":"vid_01","youtubeId":"kZusYOYxpA8","title":"K’anba: cuevas y río Cahabón","description":"Un recorrido audiovisual por los pasadizos, el río subterráneo y el entorno de Semuc Champey.","category":"Cueva"},{"id":"vid_02","youtubeId":"vjk9xwiBmMs","title":"La cueva de los Goonies","description":"Así se siente avanzar a oscuras, con luz frontal al cuello, entre roca y agua.","category":"Aventura"},{"id":"vid_03","youtubeId":"Ia55CKzelwk","title":"Semuc Champey desde el mirador","description":"La vista que explica por qué este rincón de Alta Verapaz es irrepetible.","category":"Entorno"},{"id":"vid_04","youtubeId":"dG2SJhAwo1s","title":"Saltos, cuevas y tubing","description":"La combinación clásica: cueva, cascada, columpio y flotada por el Cahabón.","category":"Aventura"},{"id":"vid_05","youtubeId":"-hWjchb0uFI","title":"Cobán y Lanquín en ruta","description":"El camino hacia las cuevas: montaña, neblina y comunidades q’eqchi’.","category":"Ruta"},{"id":"vid_06","youtubeId":"CCIO_iSdJVI","title":"Guía de viaje: Semuc Champey","description":"Consejos prácticos para combinar las pozas, el mirador y la cueva en un solo día.","category":"Guía"}]}'::jsonb,
  'tours', '[]'::jsonb,
  'reservations', '[]'::jsonb,
  'closures', '[]'::jsonb,
  'refunds', '[]'::jsonb,
  'emails', '[]'::jsonb,
  'settings', '{
    "business": {"legalName":"","nit":"","address":"","phone":"","email":""},
    "booking": {"holdMinutes":20,"advanceDays":120,"cutoffHours":2,"currency":"GTQ","exchangeRate":7.8,"maxSeatsPerOrder":12},
    "payments": {"provider":"KanbaPay Sandbox","mode":"sandbox","merchantId":"","publicKey":"","statement":"KANBA CUEVAS"},
    "smtp": {"host":"","port":465,"secure":true,"user":"","fromEmail":"","fromName":""}
  }'::jsonb
))
ON CONFLICT (id) DO NOTHING;
COMMIT;
